from pathlib import Path
p=Path("src/styles.css");s=p.read_text(encoding="utf-8");css='/* public-ux-v15 */\n.stats-table,.coach-table{max-height:min(72vh,760px);position:relative}\n.stats-table table,.coach-table table{border-collapse:separate;border-spacing:0;min-width:max-content}\n.stats-table thead th,.coach-table thead th{position:sticky;top:0;z-index:4;background:#eaf4ee;box-shadow:0 1px 0 #cfdad3}\n.stats-table .rank-col{position:sticky;left:0;z-index:5;min-width:52px;width:52px;background:#f7faf8}\n.stats-table .name-col{position:sticky;left:52px;z-index:3;min-width:190px;background:#fff;box-shadow:5px 0 9px -8px #17201b}\n.stats-table thead .rank-col{z-index:8;background:#dfeee5}\n.stats-table thead .name-col{z-index:7;background:#eaf4ee}\n.coach-table .name-col{position:sticky;left:0;z-index:3;min-width:190px;background:#fff;box-shadow:5px 0 9px -8px #17201b}\n.coach-table thead .name-col{z-index:7;background:#eaf4ee}\n.recordcards{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}\n@media(max-width:800px){\n header{position:sticky;top:0;display:block;padding:8px 12px;height:auto}.brand{justify-content:center}.brand img{height:42px;width:34px}.brand b{font-size:16px}header nav{display:flex;overflow-x:auto;flex-wrap:nowrap;justify-content:flex-start;gap:6px;padding:8px 0 2px;scrollbar-width:none}header nav::-webkit-scrollbar{display:none}header nav a,header nav button{white-space:nowrap;padding:7px 9px;border-radius:8px;background:#f1f6f3}\n main{padding:20px 12px 60px}.sectiontitle{font-size:clamp(1.5rem,7vw,2rem);margin:20px 0 13px}.hero{min-height:auto;border-radius:18px;padding:28px 20px}.hero h1{font-size:32px;letter-spacing:-1px}.hero p{font-size:15px;margin-bottom:20px}\n .metricgrid{gap:9px;margin:16px 0 28px!important}.metric{padding:14px!important;border-radius:12px}.metric strong{font-size:1.75rem!important}.metric span{font-size:.78rem!important}.cards{gap:9px;margin:16px 0 30px}.card{padding:14px;border-radius:12px}.card h3{font-size:.92rem;margin:3px 0 7px}.card strong{font-size:1.9rem}.card p{font-size:.8rem;margin:4px 0}.card.gold{border-top-width:4px}.recordgroup{font-size:1.15rem;margin:22px 0 10px}.recordcards,.cards{grid-template-columns:repeat(2,minmax(0,1fr))}\n .tablewrap{border-radius:12px;max-width:100%;-webkit-overflow-scrolling:touch}.stats-table,.coach-table{max-height:68vh}.stats-table th,.stats-table td,.coach-table th,.coach-table td{padding:10px 9px;font-size:.82rem}.stats-table .rank-col{min-width:40px;width:40px}.stats-table .name-col{left:40px;min-width:148px;max-width:148px;overflow:hidden;text-overflow:ellipsis}.coach-table .name-col{min-width:150px;max-width:150px;overflow:hidden;text-overflow:ellipsis}\n .filterbar,.filterbar.advanced{display:grid;grid-template-columns:1fr;gap:8px}.filterbar>*{width:100%}.season-multiselect{grid-template-columns:repeat(2,minmax(0,1fr));padding:12px;gap:8px}.season-quick{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.season-quick button{padding:8px 4px;font-size:.75rem}\n .match{padding:13px;display:grid;gap:6px}.match strong{text-align:left;font-size:.95rem}.score{margin:0 4px}.detailhero{padding:20px;border-radius:16px}.formationrow{grid-template-columns:72px 1fr;padding:11px 13px}.squadgrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.squadperson{padding:10px;font-size:.86rem}.chartpanel{padding:12px;margin:18px 0;border-radius:14px}.usage-split article{padding:15px}.admin-tabs{overflow-x:auto;flex-wrap:nowrap;scrollbar-width:none}.admin-tabs button{white-space:nowrap}.admin-section{padding:14px}.player-picker{grid-template-columns:repeat(2,minmax(0,1fr))}.player-picker button{min-height:62px;padding:9px}.event-admin-row{gap:6px}\n}\n@media(max-width:420px){.recordcards,.cards{grid-template-columns:repeat(2,minmax(0,1fr))!important}.metricgrid{grid-template-columns:repeat(2,minmax(0,1fr))!important}.card h3{font-size:.8rem}.card strong{font-size:1.55rem}.hero h1{font-size:28px}.season-quick{grid-template-columns:repeat(2,1fr)}}\n'
if "public-ux-v15" not in s:p.write_text(s+"\n"+css+"\n",encoding="utf-8")
